arguments.command:
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The query key must use only A-Z a-z 0-9 _ . - (Cirrus function URL rejects other keys with 400).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`（キーに `/` などは使えない。docs/platform/cirrus-functions.md 参照）|' docs/framework.md
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
out=$(bash bin/render event)
echo "$out" | grep -q 'action=' || { echo "render"; fail=1; }
# every rendered query key must be valid for the Cirrus function URL
for u in $(echo "$out" | grep -o 'action="[^"]*"' | sed 's/action="\?//;s/"$//'); do
  k=${u#\?}; k=${k%%=*}
  echo "$k" | grep -Eq '^[A-Za-z0-9_.-]+$' || { echo "invalid query key: $k"; fail=1; }
done
for p in 'events/1/edit:save' 'events/1/seats:assign' 'orders/1/refund:refund'; do
  bash bin/handle POST "/${p%%:*}?action=${p##*:}" | grep -q "^200 ${p##*:}" || { echo "handle $p"; fail=1; }
done
bash bin/handle POST '/events/1/edit?action=bogus' | grep -q '^404' || { echo "bogus"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo $?; bash bin/render event

